const item = $json;

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const rnd = n => Math.floor(Math.random() * n);
const pick = a => a[rnd(a.length)];
const num = (a, b) => a + Math.random() * (b - a);
const split2 = (s, fbT, fbD) => {
  const t = String(s || '');
  const m = t.split(/\s*[:–—-]\s+/);
  if (m.length > 1) return [m[0].replace(/^(?:card|step|touch|prompt)\s*\d*[:.-]?\s*|^\d+[.)]\s*/i, '').trim(), m.slice(1).join(' ').trim()];
  return [fbT, t.trim() || fbD];
};
const toMin = s => {
  const m = String(s || '').match(/(\d+(?:\.\d+)?)\s*(hours?|hrs?|h|minutes?|mins?|m)\b/i);
  if (!m) return null;
  const n = parseFloat(m[1]);
  return /^h/i.test(m[2]) ? n * 60 : n;
};

