const angle = Math.round(num(155, 175));

// Helper to format headline: power punchline gets luminous gradient highlight
function formatHeadline(hl) {
  const text = String(hl || 'THE AI FREELANCER BLUEPRINT').trim();
  const words = text.split(/\s+/);
  if (words.length <= 2) {
    return `<span class="hl-grad">${esc(text)}</span>`;
  }
  const splitIdx = Math.max(1, Math.floor(words.length / 2));
  const firstHalf = words.slice(0, splitIdx).join(' ');
  const secondHalf = words.slice(splitIdx).join(' ');
  return `${esc(firstHalf)} <span class="hl-grad">${esc(secondHalf)}</span>`;
}

// Atmospheric lighting & subtle tech matrix pattern
function renderAtmosphere() {
  const glow = `<div class="mesh-glow"></div>`;
  if (decorVariant === 'grid') {
    return `
    ${glow}
    <svg width="1000" height="1500" class="tech-pattern">
      <defs>
        <pattern id="techgrid" width="44" height="44" patternUnits="userSpaceOnUse">
          <path d="M44 0H0V44" fill="none" stroke="${P.dark ? 'rgba(255,255,255,0.06)' : 'rgba(15,23,42,0.04)'}" stroke-width="1.2"/>
        </pattern>
        <radialGradient id="gridFade" cx="50%" cy="30%" r="65%">
          <stop offset="0%" stop-color="#fff" stop-opacity="1"/>
          <stop offset="70%" stop-color="#fff" stop-opacity="0.3"/>
          <stop offset="100%" stop-color="#fff" stop-opacity="0.05"/>
        </radialGradient>
        <mask id="gridMask"><rect width="1000" height="1500" fill="url(#gridFade)"/></mask>
      </defs>
      <rect width="1000" height="1500" fill="url(#techgrid)" mask="url(#gridMask)"/>
      <circle cx="500" cy="220" r="450" fill="none" stroke="${P.a}" stroke-width="1.5" stroke-dasharray="8 12" opacity="${P.dark ? '0.22' : '0.12'}"/>
    </svg>`;
  }
  if (decorVariant === 'blobs') {
    return `
    ${glow}
    <svg width="1000" height="1500" class="tech-pattern">
      <defs>
        <filter id="meshBlur"><feGaussianBlur stdDeviation="80"/></filter>
      </defs>
      <circle cx="200" cy="240" r="220" fill="${P.a}" opacity="${P.dark ? '0.20' : '0.12'}" filter="url(#meshBlur)"/>
      <circle cx="800" cy="800" r="280" fill="${P.b}" opacity="${P.dark ? '0.18' : '0.10'}" filter="url(#meshBlur)"/>
      <circle cx="500" cy="1300" r="240" fill="${P.accent}" opacity="${P.dark ? '0.15' : '0.08'}" filter="url(#meshBlur)"/>
    </svg>`;
  }
  if (decorVariant === 'arcs') {
    return `
    ${glow}
    <svg width="1000" height="1500" class="tech-pattern">
      <circle cx="500" cy="240" r="320" fill="none" stroke="${P.a}" stroke-width="2" stroke-dasharray="10 16" opacity="${P.dark ? '0.30' : '0.16'}"/>
      <circle cx="500" cy="240" r="480" fill="none" stroke="${P.b}" stroke-width="1.5" stroke-dasharray="14 20" opacity="${P.dark ? '0.22' : '0.12'}"/>
      <circle cx="500" cy="240" r="640" fill="none" stroke="${P.a}" stroke-width="1" opacity="${P.dark ? '0.15' : '0.08'}"/>
    </svg>`;
  }
  // Default 'dots'
  return `
  ${glow}
  <svg width="1000" height="1500" class="tech-pattern">
    <defs>
      <pattern id="dotpattern" width="36" height="36" patternUnits="userSpaceOnUse">
        <circle cx="2" cy="2" r="1.6" fill="${P.dark ? 'rgba(255,255,255,0.08)' : 'rgba(15,23,42,0.06)'}"/>
      </pattern>
      <radialGradient id="centerFade" cx="50%" cy="35%" r="65%">
        <stop offset="0%" stop-color="#fff" stop-opacity="1"/>
        <stop offset="65%" stop-color="#fff" stop-opacity="0.3"/>
        <stop offset="100%" stop-color="#fff" stop-opacity="0.05"/>
      </radialGradient>
      <mask id="patternMask">
        <rect width="1000" height="1500" fill="url(#centerFade)"/>
      </mask>
    </defs>
    <rect width="1000" height="1500" fill="url(#dotpattern)" mask="url(#patternMask)"/>
    <circle cx="500" cy="220" r="420" fill="none" stroke="${P.a}" stroke-width="1.5" stroke-dasharray="6 10" opacity="${P.dark ? '0.25' : '0.15'}"/>
    <circle cx="500" cy="220" r="580" fill="none" stroke="${P.b}" stroke-width="1" opacity="${P.dark ? '0.18' : '0.10'}"/>
  </svg>`;
}

// Reusable SVG Icons
