// ---------- 8 Studio Body Layouts ----------
function s1() { // 6-Card Prompt Grid
  const defs = [
    ['3-Tier Package Creator', 'Package my service into 3 offers'],
    ['Value-Based ROI Anchor', 'Calculate financial upside for 10x ROI'],
    ['Scope Creep Defense', 'Write polite boundary script clarifying extra scope'],
    ['Monthly Retainer Pitch', 'Generate monthly maintenance proposal on autopay'],
    ['Rush Fee Multiplier', 'Apply expedited priority fee for rush jobs'],
    ['Discount Counter-Offer', 'Hold price firm by trimming deliverables']
  ];
  const cards = [1, 2, 3, 4, 5, 6].map((n, i) => {
    const [t, d] = split2(item['card' + n], defs[i][0], defs[i][1]);
    return `
    <div class="glass-card s1-card">
      <div class="card-head">
        <div class="number-badge">0${n}</div>
        <div class="corner-arrow">↗</div>
      </div>
      <div class="card-title clamp2">${esc(t)}</div>
      <div class="card-desc clamp3">${esc(d)}</div>
    </div>`;
  }).join('');
  return `<div class="grid6-container">${cards}</div>`;
}

function s2() { // 2x2 Quadrant Matrix
  const cols = [
    ['col1', 'WHAT TO RESEARCH', ['Target audience', 'Recent launches', 'Public gaps', 'Budget signals']],
    ['col2', 'CLUES TO MINE', ['Job post subtext', 'Implied pain', 'Tech stack', 'Hiring urgency']],
    ['col3', 'CHATGPT PROMPTS', ['Prospect Snapshot', 'Angle Builder', 'Pain Finder', 'ROI Calculator']],
    ['col4', 'HOW TO HOOK', ['Personal opening', 'Outcome-focused', 'Proof point', 'Zero-risk offer']]
  ];
  const hues = [P.a, P.b, '#f59e0b', '#ec4899'];
  const cards = cols.map(([k, ft, fi], i) => {
    const title = esc(item[k + 'Title'] || ft);
    const items = (String(item[k + 'Text'] || '').split(/[\n,•]/).map(x => x.trim()).filter(Boolean).slice(0, 4));
    const list = (items.length ? items : fi).map(x => `
      <li class="matrix-li">
        <span class="matrix-dot" style="background:${hues[i]};box-shadow:0 0 8px ${hues[i]}"></span>
        <span class="clamp1">${esc(x)}</span>
      </li>`).join('');
    return `
    <div class="glass-card matrix-card" style="border-top:6px solid ${hues[i]};box-shadow:0 -4px 18px ${hues[i]}33">
      <div class="matrix-head" style="color:${hues[i]}">
        <span class="matrix-icon">✦</span>
        <span class="clamp1">${title}</span>
      </div>
      <ul class="matrix-list">${list}</ul>
    </div>`;
  }).join('');
  return `<div class="matrix-grid">${cards}</div>`;
}

