      <div class="ai-badge">STEP 0${i + 1}</div>
      <div class="ai-text clamp1">${esc(b)}</div>
    </div>`).join('');
  const pills = ['Under 250 Words', 'Zero Fluff', 'No Resume Dumping', 'Clear Next Step'].map(t => `
    <div class="glass-card feature-pill">
      <div class="feature-icon">${ICON_CHECK}</div>
      <span>${t}</span>
    </div>`).join('');

  return `
