}

function s4() { // Drip Roadmap Timeline
  const defs = [
    ['Small Value Drop', 'Add fresh relevant industry insight'],
    ['The Proof Point', 'Share a mini case study or quick metric'],
    ['The Clean Breakup', 'Gracefully close the loop and release pressure']
  ];
  const days = ['DAY 03', 'DAY 07', 'DAY 14'];
  const rows = [1, 2, 3].map((n, i) => {
    const [t, d] = split2(item['touch' + n], defs[i][0], defs[i][1]);
    return `
    <div class="roadmap-row">
      <div class="roadmap-orb" style="background:linear-gradient(135deg,${P.a},${P.b})">
        <small>TOUCH 0${n}</small>
        <strong>${days[i]}</strong>
      </div>
      <div class="glass-card roadmap-card">
        <div class="roadmap-card-head">
          <span class="roadmap-tag">HIGH CONVERSION</span>
          <span class="corner-arrow">↗</span>
        </div>
        <div class="roadmap-title clamp2">${esc(t)}</div>
        <div class="roadmap-desc clamp3">${esc(d)}</div>
      </div>
    </div>`;
  }).join('');
  return `
  <div class="roadmap-container">
    <div class="roadmap-laser-line" style="background:linear-gradient(180deg,${P.a},${P.b})"></div>
    ${rows}
  </div>`;
}

function s5() { // Amateur vs 6-Figure Pro Split
  const bad = [
    item.bad1 || 'Sending 500-word walls of resume text',
    item.bad2 || 'Competing on the lowest hourly rate',
    item.bad3 || 'Pitching generic services without diagnosis'
  ];
  const good = [
    item.good1 || '280-word ChatGPT diagnostic hook Line 1',
    item.good2 || '3-tier value packages $500 - $1,500 - $3,500',
    item.good3 || 'Concrete 3-bullet execution plan with milestones'
  ];
  const badItems = bad.map(x => `
    <div class="split-li bad-li">
      <div class="split-icon bad-icon">${ICON_X}</div>
      <span class="clamp2">${esc(x)}</span>
    </div>`).join('');
  const goodItems = good.map(x => `
    <div class="split-li good-li">
      <div class="split-icon good-icon">${ICON_CHECK}</div>
