function s6() { // 5-Point QA Checklist
  const defs = [
    'Identify 1 specific revenue leak on their website',
    'Mirror their core problem before mentioning services',
    'Lay out a 3-bullet execution plan with exact dates',
    'Include 1 real metric proof point e.g. 24% lift',
    'End with a low-friction zero-risk ask'
  ];
  const rows = [1, 2, 3, 4, 5].map(n => `
    <div class="glass-card checklist-row">
      <div class="check-circle" style="background:linear-gradient(135deg,${P.a},${P.b})">${ICON_CHECK}</div>
      <span class="check-text clamp2">${esc(String(item['check' + n] || defs[n - 1]).replace(/^\d+[.)]\s*/, ''))}</span>
    </div>`).join('');
  const gr = esc(item.goldenRule || 'Diagnosis beats generic proposals every single time');
  return `
  <div class="checklist-container">
    <div class="glass-card checklist-gate-header">
      <div>
        <div class="gate-title">PRE-FLIGHT QUALITY GATE</div>
        <div class="gate-sub">Never send a client proposal without all 5 verified</div>
      </div>
      <div class="gate-ring" style="background:linear-gradient(135deg,${P.a},${P.b})">
        <span>5/5</span>
        <small>PASSED</small>
      </div>
    </div>
    <div class="checklist-items-stack">${rows}</div>
    <div class="golden-rule-banner">
      <span class="gold-spark">★</span>
      <span><strong>GOLDEN RULE:</strong> ${gr}</span>
    </div>
  </div>`;
}

function s7() { // Ascending Value Ladder / Staircase
  const defs = [
    ['TIER 01: DIAGNOSTIC AUDIT', '$500 · Identify revenue leak, benchmark competitors'],
    ['TIER 02: CORE SPRINT', '$1,500 · Deliver complete AI automated workflow'],
    ['TIER 03: GROWTH RETAINER', '$5,000/mo · Continuous optimization & strategic advisory']
  ];
  const hs = [330, 470, 610];
  const cols = [P.a, P.b, '#f59e0b'];
  const steps = [1, 2, 3].map((n, i) => `
    <div class="glass-card ladder-step" style="height:${hs[i]}px;border-top:6px solid ${cols[i]};">
      <div class="step-num-bg">0${n}</div>
      <div class="step-badge" style="background:linear-gradient(135deg,${cols[i]},${cols[i]}cc)">STEP 0${n}</div>
      <div class="step-title clamp3">${esc(item['step' + n + 'Title'] || defs[i][0])}</div>
      <div class="step-desc clamp3">${esc(item['step' + n + 'Desc'] || defs[i][1])}</div>
    </div>`).join('');

  const arrow = `
  <svg class="ladder-trajectory" width="900" height="120" viewBox="0 0 900 120">
    <path d="M40 100 C300 85 550 55 860 20" fill="none" stroke="${P.a}" stroke-width="6" stroke-dasharray="6 12" stroke-linecap="round"/>
    <polygon points="860,20 835,10 842,35" fill="${P.a}"/>
  </svg>`;

  return `<div class="ladder-container">${arrow}${steps}</div>`;
}

function s8() { // Time-Saver Comparison Table / Metric Bar Chart
  const d = [
    ['Prospect Research', '45m browsing', '10m AI snapshot'],
    ['Proposal Writing', '60m drafting', '15m 280-word hook'],
    ['Ghosted Clients', '30m awkward emails', '5m 3-touch cadence'],
    ['Pricing & Scope', '40m haggling', '10m 3-tier SOW']
  ];
  const rows = [1, 2, 3, 4].map((n, i) => {
    const task = item['r' + n + 'Task'] || d[i][0], o = item['r' + n + 'Old'] || d[i][1], w = item['r' + n + 'New'] || d[i][2];
    return { task, o, w, om: toMin(o), wm: toMin(w) };
  });
  const allNum = rows.every(r => r.om && r.wm);
  const max = allNum ? Math.max(...rows.map(r => r.om)) : 1;
  const saved = allNum ? Math.round(rows.reduce((a, r) => a + r.om - r.wm, 0)) : 115;

  const cards = rows.map(r => {
    const ow = allNum ? Math.max(35, (r.om / max) * 100) : 100;
    const nw = allNum ? Math.max(25, (r.wm / max) * 100) : 30;
    return `
    <div class="glass-card table-row-card">
      <div class="table-row-head">
        <span class="table-task-name">${esc(r.task)}</span>
        <span class="time-savings-pill">-75% TIME</span>
      </div>
      <div class="bar-track">
        <div class="bar-fill bar-old" style="width:${ow}%">
          <span>${esc(r.o)}</span>
        </div>
      </div>
      <div class="bar-track">
        <div class="bar-fill bar-new" style="width:${nw}%;background:linear-gradient(90deg,${P.a},${P.b})">
          <span>⚡ ${esc(r.w)}</span>
        </div>
      </div>
    </div>`;
  }).join('');

  return `
  <div class="table-container">
    <div class="table-legend">
      <span class="legend-item"><i style="background:#ef4444"></i> MANUAL SLOW WAY</span>
      <span class="legend-item"><i style="background:${P.a}"></i> ⚡ THE AI PLAYBOOK WAY</span>
    </div>
    <div class="table-cards-stack">${cards}</div>
    <div class="table-total-banner">
      <span>⏱ <strong>TOTAL BENEFIT:</strong> SAVE ~${saved} MINUTES PER CLIENT ON AUTOPILOT</span>
    </div>
  </div>`;
}

